  E('blind_sprite', { n: 'Слепой росток', ic: '🌱', role: 'skirm', tags: ['plant'], sk: ['e_thorn', 'e_vines', 'e_hit'], weak: ['fire'], res: ['phys'], loot: [['herb_g', 0.6, 1, 2], ['dust', 0.3, 1, 2]] });
